SET NAMES utf8mb4;
START TRANSACTION;
CREATE TEMPORARY TABLE device_order_reconcile (client_order_id CHAR(36) PRIMARY KEY, order_id INT NOT NULL, transaction_at DATETIME NOT NULL, table_number VARCHAR(255) NOT NULL, payment_method VARCHAR(32) NOT NULL, total_amount INT NOT NULL, paid_amount INT NOT NULL, change_amount INT NOT NULL, status_order VARCHAR(32) NOT NULL);
SELECT 'device_rows' check_name, COUNT(*) check_value FROM device_order_reconcile;
SELECT 'matched_rows' check_name, COUNT(*) check_value FROM device_order_reconcile d JOIN mobile_sync_orders m ON m.client_order_id=d.client_order_id AND m.order_id=d.order_id JOIN orders o ON o.id=m.order_id;
UPDATE orders o JOIN mobile_sync_orders m ON m.order_id=o.id JOIN device_order_reconcile d ON d.client_order_id=m.client_order_id AND d.order_id=o.id SET o.created_at=d.transaction_at,o.table_number=d.table_number,o.payment_method=d.payment_method,o.total_amount=d.total_amount,o.paid_amount=d.paid_amount,o.change_amount=d.change_amount,o.status_order=d.status_order;
SELECT 'updated_rows' check_name, ROW_COUNT() check_value;
DELETE FROM order_items WHERE id_tr=191;
DELETE FROM order_carwash WHERE id_tr=191;
SELECT 'order_191_item_total' check_name, COALESCE((SELECT SUM(total) FROM order_items WHERE id_tr=191),0)+COALESCE((SELECT SUM(total) FROM order_carwash WHERE id_tr=191),0) check_value;
COMMIT;
